// Bollard UI — reading-level · MIT licence · https://bollard-ui.vercel.app/components/reading-level

/** Wordy words and phrases with a plainer swap (plainlanguage.gov, GOV.UK style). Keys are lowercase. */
export const PLAIN_WORDS: Record<string, string> = {
  utilize: "use", utilise: "use", utilization: "use", commence: "start", commencement: "start", terminate: "end",
  approximately: "about", assistance: "help", purchase: "buy", sufficient: "enough", additional: "more",
  numerous: "many", demonstrate: "show", facilitate: "help", "prior to": "before", "in order to": "to",
  subsequently: "later", endeavor: "try", endeavour: "try", obtain: "get", inquire: "ask", enquire: "ask",
  modify: "change", initiate: "start", regarding: "about", ascertain: "find out", nevertheless: "still",
  "in the event that": "if", "at this point in time": "now", "due to the fact that": "because",
  individuals: "people", remuneration: "pay", expedite: "speed up", consequently: "so", notify: "tell",
  aforementioned: "this", "in accordance with": "under", "with regard to": "about", "a number of": "some",
  discontinue: "stop", transmit: "send", possess: "have", reside: "live", whilst: "while", henceforth: "from now on",
  // Common inflections, so "utilized" and "purchasing" are caught too.
  utilized: "used", utilizes: "uses", utilizing: "using", utilised: "used", utilising: "using", commenced: "started",
  commences: "starts", terminated: "ended", purchased: "bought", purchasing: "buying", purchases: "buys",
  demonstrated: "showed", demonstrates: "shows", facilitates: "helps", facilitated: "helped", obtained: "got",
  obtaining: "getting", modified: "changed", modifying: "changing", initiated: "started", notified: "told",
  transmitted: "sent", discontinued: "stopped", inquired: "asked", enquired: "asked",
}

/** Every place `word` occurs, as whole words, in the order they appear. */
export function findWord(text: string, word: string) {
  const pattern = word.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+")
  return [...text.matchAll(new RegExp(`(?<![\\p{L}\\p{N}])${pattern}(?![\\p{L}\\p{N}])`, "giu"))].map((m) => ({ start: m.index, end: m.index + m[0].length, match: m[0] }))
}

/** `plain` with the capital of the word it replaces. */
export const matchCase = (original: string, plain: string) => (/^\p{Lu}/u.test(original) ? plain.charAt(0).toUpperCase() + plain.slice(1) : plain)

const ABBREVIATIONS = /\b(e\.g|i\.e|etc|vs|mr|mrs|ms|dr|prof|st|no|approx|fig|inc|ltd|jr|sr|[A-Z])\.$/i
const WORD = /[\p{L}\p{N}][\p{L}\p{N}'’-]*/gu

// Vowel pairs that are usually two syllables (po-em, li-on, ac-tu-al, i-de-a), and endings that add or drop one.
const SPLIT_PAIRS = [/oe(?!s?$)/g, /(?<![cgst])ia/g, /(?<![cgstxn]|ll)io(?!u)/g, /iu/g, /(?<![gq])ua/g, /uo/g, /(?<![pg])eo/g, /(?<![tcu])ie(?:t|n[tc])/g, /^scien/g]
const ADD_END = [/(?<![aeiou])[eo]ing$/, /ism$/, /ie(?:r|st)$/, /[ds]nt$/]

/** Vowel-group syllable estimate with the usual silent-e, -ed and vowel-split fixes (accurate to roughly ±10%). */
export function countSyllables(word: string) {
  const w = word.toLowerCase().replace(/[^a-z]/g, "")
  if (!w) return 1
  if (w.length <= 3) return 1
  const trimmed = w.replace(/(?:[^laeiouy]es|(?<![td])ed|[^laeiouy]e)$/, "").replace(/^y/, "")
  let count = trimmed.match(/[aeiouy]{1,2}/g)?.length ?? 1
  for (const pair of SPLIT_PAIRS) count += trimmed.match(pair)?.length ?? 0
  for (const end of ADD_END) if (end.test(trimmed)) count++
  if (/ea$|^creat(?!ur)/.test(w)) count++
  if (/[^aeiouy]ely$/.test(w)) count--
  if (/[cgtx]iou/.test(w)) count--
  return Math.max(1, count)
}

/** Share of letters that are Latin (1 for text without letters). */
const latinShare = (text: string) => {
  const letters = text.match(/\p{L}/gu)?.length ?? 0
  return letters ? (text.match(/[a-z\u00c0-\u024f]/gi)?.length ?? 0) / letters : 1
}

const STOPWORDS = new Set("the a an and or but to of in on at for from with by as is are was were be been it its this that these those you your we our they their he she his her i me my not no if can will would should have has had do does did so than then there here what which who when where how all any some more just about into out up".split(" "))

export type ReadabilitySupport = "ok" | "script" | "language"

/**
 * Whether an English grade means anything for this text. "script": mostly non-Latin letters (Hindi, Marathi,
 * Arabic...). "language": Latin letters but almost none of the small words every English text is full of.
 */
export function readabilitySupport(text: string): ReadabilitySupport {
  if ((text.match(/\p{L}/gu)?.length ?? 0) >= 8 && latinShare(text) < 0.7) return "script"
  const words = (text.toLowerCase().match(/[a-z]+(?:['’][a-z]+)?/g) ?? [])
  const common = words.filter((w) => STOPWORDS.has(w)).length
  if (words.length >= 12 && common / words.length < 0.1) return "language"
  return "ok"
}

/** Flesch-Kincaid grade: 0.39 × words per sentence + 11.8 × syllables per word − 15.59. */
export const fleschKincaid = (words: number, sentences: number, syllables: number) =>
  words && sentences ? Math.max(0, 0.39 * (words / sentences) + 11.8 * (syllables / words) - 15.59) : 0

export interface Sentence {
  start: number
  end: number
  words: number
  syllables: number
  grade: number
}

/** Splits text into sentences, keeping e.g., Dr., initials, decimals and new lines (list items, headings) right. */
export function splitSentences(text: string): Sentence[] {
  const out: Sentence[] = []
  let start = 0
  const push = (end: number) => {
    const body = text.slice(start, end).replace(/https?:\/\/\S+/g, "link")
    const tokens = body.match(WORD) ?? []
    if (tokens.length) {
      const syllables = tokens.reduce((sum, t) => sum + (/^\d/.test(t) ? 1 : countSyllables(t)), 0)
      const lead = text.slice(start, end).search(/\S/)
      out.push({ start: start + lead, end, words: tokens.length, syllables, grade: fleschKincaid(tokens.length, 1, syllables) })
    }
    start = end
  }
  for (let i = 0; i < text.length; i++) {
    const ch = text[i]
    if (ch === "\n") push(i)
    else if (/[.!?]/.test(ch) && !/[.!?]/.test(text[i + 1] ?? "")) {
      const next = text.slice(i + 1).match(/^["'’)\]]*\s+(\S)/)?.[1]
      if (i + 1 < text.length && (!next || /[\p{Ll}\d]/u.test(next) || (ch === "." && ABBREVIATIONS.test(text.slice(Math.max(0, i - 6), i + 1))))) continue
      let end = i + 1
      while (/["'’)\]]/.test(text[end] ?? "")) end++
      push(end)
    }
  }
  push(text.length)
  return out
}

export type Difficulty = "hard" | "very-hard"

export interface ReadabilityReport {
  /** "ok", or why the English grade was skipped. When not "ok", grade is 0 and no sentence is flagged. */
  support: ReadabilitySupport
  grade: number
  words: number
  sentences: (Sentence & { difficulty?: Difficulty; long: boolean; dense: boolean })[]
  swaps: { start: number; end: number; word: string; plain: string }[]
}

/**
 * Grades the text and marks hard sentences relative to the target. A sentence is only flagged when it is long
 * enough to matter (12+ words) and dense, or very long: a long run of short words isn't hard to read.
 */
export function analyzeReadability(text: string, { targetGrade = 8, swaps = PLAIN_WORDS }: { targetGrade?: number; swaps?: Record<string, string> } = {}): ReadabilityReport {
  const support = readabilitySupport(text)
  // A line in another script inside English text (a Hindi greeting) is left out of the grade.
  const graded = splitSentences(text).filter((s) => support !== "ok" || latinShare(text.slice(s.start, s.end)) >= 0.5)
  const sentences = graded.map((s) => {
    const perWord = s.syllables / s.words
    const long = s.words > 22
    const dense = perWord >= 1.6
    const counts = support === "ok" && s.words >= 12 && (perWord >= 1.4 || s.words >= 28)
    const difficulty: Difficulty | undefined = !counts ? undefined : s.grade >= targetGrade + 6 ? "very-hard" : s.grade >= targetGrade + 2 ? "hard" : undefined
    return { ...s, difficulty, long, dense }
  })
  const words = sentences.reduce((sum, s) => sum + s.words, 0)
  const syllables = sentences.reduce((sum, s) => sum + s.syllables, 0)
  const keys = Object.keys(swaps).sort((a, b) => b.length - a.length).map((k) => k.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/ /g, "\\s+"))
  const found = keys.length ? [...text.matchAll(new RegExp(`(?<![\\p{L}\\p{N}])(${keys.join("|")})(?![\\p{L}\\p{N}])`, "giu"))] : []
  return {
    support,
    grade: support === "ok" ? Math.round(fleschKincaid(words, sentences.length, syllables) * 10) / 10 : 0,
    words,
    sentences,
    swaps: found.map((m) => ({ start: m.index, end: m.index + m[0].length, word: m[0], plain: swaps[m[0].toLowerCase().replace(/\s+/g, " ")] })),
  }
}

/** Replaces every use of a wordy word, keeping a leading capital. */
export function applySwap(text: string, word: string, plain: string) {
  return findWord(text, word).reduceRight((out, m) => out.slice(0, m.start) + matchCase(m.match, plain) + out.slice(m.end), text)
}

"use client"

// Bollard UI — reading-level · MIT licence · https://bollard-ui.vercel.app/components/reading-level

import * as React from "react"
import { ArrowRight, BookOpen, Languages } from "lucide-react"

import { cn } from "@/lib/utils"
import { analyzeReadability, applySwap, findWord, matchCase, PLAIN_WORDS, type ReadabilityReport } from "./readability"

export { analyzeReadability, applySwap, countSyllables, findWord, fleschKincaid, PLAIN_WORDS, readabilitySupport, splitSentences } from "./readability"
export type { Difficulty, ReadabilityReport, ReadabilitySupport, Sentence } from "./readability"

/** Plain-English band for a grade. Override to translate. */
export const READING_BANDS: [maxGrade: number, label: string][] = [
  [6, "Easy for most readers"],
  [9, "Plain English"],
  [12, "Fairly hard"],
  [Infinity, "Hard: college level"],
]

const MARK = {
  hard: "bg-amber-300/45 dark:bg-amber-400/25",
  "very-hard": "bg-red-300/45 dark:bg-red-500/30",
  swap: "bg-violet-300/50 dark:bg-violet-400/30",
}
const chipClass =
  "inline-flex h-7 items-center gap-1 rounded-md border px-2 text-xs transition-colors hover:bg-accent outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"

/** Splits the text at every sentence and swap boundary so the backdrop can tint each piece. */
function segments(text: string, report: ReadabilityReport) {
  const cuts = new Set([0, text.length])
  report.sentences.forEach((s) => s.difficulty && (cuts.add(s.start), cuts.add(s.end)))
  report.swaps.forEach((s) => (cuts.add(s.start), cuts.add(s.end)))
  const points = [...cuts].sort((a, b) => a - b)
  return points.slice(0, -1).map((from, i) => {
    const to = points[i + 1]
    const swap = report.swaps.some((s) => s.start <= from && s.end >= to)
    const sentence = report.sentences.find((s) => s.difficulty && s.start <= from && s.end >= to)
    return { text: text.slice(from, to), tone: swap ? MARK.swap : sentence ? MARK[sentence.difficulty!] : "" }
  })
}

export interface ReadingLevelProps extends Omit<React.ComponentProps<"textarea">, "value" | "defaultValue" | "onChange"> {
  /** Visible label. */
  label?: string
  /** Text (controlled). */
  value?: string
  /** Starting text when uncontrolled. */
  defaultValue?: string
  /** Called with the new text on every edit or swap. */
  onValueChange?: (value: string) => void
  /** US school grade to aim for. 8 suits most public writing. */
  targetGrade?: number
  /** Wordy word → plain swap. */
  swaps?: Record<string, string>
  /** How many of the hardest sentences to list. */
  maxSentences?: number
  /** Plain-English band labels per grade range. Override to translate. */
  bands?: typeof READING_BANDS
  /** `{grade}` is filled in. */
  gradeText?: string
  /** `{target}` is filled in. */
  targetText?: string
  /** Heading above the list of hardest sentences. */
  hardTitle?: string
  /** `{words}` is filled in. */
  longText?: string
  /** Reason shown for a sentence that is dense rather than just long. */
  denseText?: string
  /** Heading above the plain-word swaps. */
  swapsTitle?: string
  /** Accessible label of a swap. `{word}` and `{plain}` are filled in. */
  swapLabel?: string
  /** Announced when the grade is above the target. */
  aboveTargetText?: string
  /** Announced when the grade is at or below the target. */
  onTargetText?: string
  /** Shown instead of a grade when the text isn't English (Hindi, Marathi, French...), where the formula means nothing. */
  unsupportedText?: string
  /** Second line of the unsupported state. */
  unsupportedHint?: string
}

/**
 * A text field that keeps writing readable for its audience: a live Flesch-Kincaid grade against a target, the
 * hardest sentences tinted in place (only when long and dense, so plain long sentences aren't nagged) with the
 * reason and a jump to each, and one-tap swaps for wordy words (utilize → use).
 */
export function ReadingLevel({
  label = "Text",
  value,
  defaultValue = "",
  onValueChange,
  targetGrade = 8,
  swaps = PLAIN_WORDS,
  maxSentences = 3,
  bands = READING_BANDS,
  gradeText = "Grade {grade}",
  targetText = "aim for {target} or lower",
  hardTitle = "Hardest sentences",
  longText = "{words} words. Try splitting it.",
  denseText = "Lots of long words.",
  swapsTitle = "Plainer words",
  swapLabel = "Replace “{word}” with “{plain}”",
  aboveTargetText = "Harder than your target.",
  onTargetText = "Within your target.",
  unsupportedText = "Readability grade is English-only",
  unsupportedHint = "This text looks like another language, so no grade is shown. Short sentences and common words still help.",
  id,
  className,
  ref,
  ...props
}: ReadingLevelProps) {
  const [inner, setInner] = React.useState(defaultValue)
  const text = value ?? inner
  const field = React.useRef<HTMLTextAreaElement>(null)
  const autoId = React.useId()
  const fieldId = id ?? autoId
  React.useImperativeHandle(ref, () => field.current as HTMLTextAreaElement)

  const report = React.useMemo(() => analyzeReadability(text, { targetGrade, swaps }), [text, targetGrade, swaps])
  const hardest = report.sentences.filter((s) => s.difficulty).sort((a, b) => b.grade - a.grade).slice(0, maxSentences)
  const swapList = [...new Map(report.swaps.map((s) => [s.word.toLowerCase().replace(/\s+/g, " "), s])).values()]
  const grade = Math.round(report.grade)
  const unsupported = report.support !== "ok"
  const above = !unsupported && report.words > 0 && grade > targetGrade
  const band = bands.find(([max]) => grade <= max)?.[1]

  React.useLayoutEffect(() => {
    const el = field.current
    if (!el) return
    el.style.height = "auto"
    el.style.height = `${el.scrollHeight}px`
  }, [text])

  const set = (next: string) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }
  const chips = React.useRef<HTMLDivElement>(null)
  // The tapped chip disappears with its word, so focus moves to the next chip instead of the page.
  const refocus = React.useRef<number | null>(null)
  const focusChip = (index: number) => {
    const buttons = chips.current?.querySelectorAll("button") ?? []
    ;(buttons[Math.min(index, buttons.length - 1)] ?? field.current)?.focus()
  }
  React.useEffect(() => {
    if (refocus.current === null) return
    focusChip(refocus.current)
    refocus.current = null
  }, [text])
  const swap = (word: string, plain: string, index: number) => {
    const el = field.current
    // With a keyboard and mouse, edit through the browser so Ctrl+Z undoes the swap. Touch skips this so the
    // on-screen keyboard doesn't flash open.
    if (el && !matchMedia("(pointer: coarse)").matches) {
      el.focus()
      const hits = findWord(el.value, word).reverse()
      const done = hits.every((m) => (el.setSelectionRange(m.start, m.end), document.execCommand("insertText", false, matchCase(m.match, plain))))
      if (done) return void requestAnimationFrame(() => focusChip(index))
    }
    refocus.current = index
    set(applySwap(el?.value ?? text, word, plain))
  }
  const select = (start: number, end: number) => {
    const el = field.current
    if (!el) return
    el.focus()
    el.setSelectionRange(start, end)
  }

  return (
    <div data-slot="reading-level" data-state={unsupported ? "unsupported" : above ? "above" : "ok"} className={cn("grid w-full max-w-md gap-1.5 text-sm", className)}>
      <label htmlFor={fieldId} className="font-medium">{label}</label>
      <div className="relative rounded-md border shadow-xs transition-[color,box-shadow] focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/50 dark:bg-input/30">
        <div aria-hidden className="pointer-events-none absolute inset-0 overflow-hidden whitespace-pre-wrap break-words px-3 py-2 text-base text-transparent md:text-sm">
          {segments(text, report).map((part, i) => (part.tone ? <mark key={i} className={cn("rounded-sm text-transparent", part.tone)}>{part.text}</mark> : part.text))}
          {"\u200b"}
        </div>
        <textarea
          ref={field}
          id={fieldId}
          value={text}
          rows={4}
          onChange={(event) => set(event.target.value)}
          aria-describedby={`${fieldId}-grade`}
          className="relative block min-h-24 w-full resize-none overflow-hidden break-words bg-transparent px-3 py-2 text-base outline-none placeholder:text-muted-foreground md:text-sm"
          {...props}
        />
      </div>

      <div id={`${fieldId}-grade`} className="grid gap-1.5 pt-0.5">
        {unsupported ? (
          <div className="grid gap-0.5">
            <p className="flex items-center gap-1.5 font-medium text-muted-foreground">
              <Languages aria-hidden className="size-4" />
              {unsupportedText}
            </p>
            <p className="text-xs text-muted-foreground">{unsupportedHint}</p>
          </div>
        ) : (
          <>
            <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-0.5">
              <p className={cn("flex items-center gap-1.5 font-medium", above ? "text-amber-700 dark:text-amber-400" : "text-emerald-700 dark:text-emerald-400")}>
                <BookOpen aria-hidden className="size-4" />
                {report.words ? gradeText.replace("{grade}", String(grade)) : "–"}
                {report.words > 0 && band && <span className="font-normal text-muted-foreground">· {band}</span>}
              </p>
              <p className="text-xs text-muted-foreground">{targetText.replace("{target}", String(targetGrade))}</p>
            </div>
            <div className="relative h-1.5 rounded-full bg-muted" aria-hidden>
              <div className={cn("h-full rounded-full motion-safe:transition-[width] motion-safe:duration-300 motion-safe:ease-out", above ? "bg-amber-500" : "bg-emerald-500")} style={{ width: `${Math.min(100, (report.grade / 18) * 100)}%` }} />
              <div className="absolute -top-1 h-3.5 w-0.5 rounded-full bg-foreground/70" style={{ left: `${(targetGrade / 18) * 100}%` }} />
            </div>
          </>
        )}
        <p aria-live="polite" className="sr-only">{unsupported ? unsupportedText : report.words ? (above ? aboveTargetText : onTargetText) : ""}</p>
      </div>

      {hardest.length > 0 && (
        <div className="grid gap-1.5 pt-1">
          <p className="text-xs font-medium text-muted-foreground">{hardTitle}</p>
          <ul className="grid gap-1">
            {hardest.map((s) => (
              <li key={s.start}>
                <button type="button" onClick={() => select(s.start, s.end)} className="flex w-full min-w-0 gap-2 rounded-md p-1.5 text-left outline-none hover:bg-accent focus-visible:ring-[3px] focus-visible:ring-ring/50">
                  <span className={cn("mt-1 size-2.5 shrink-0 rounded-full", s.difficulty === "very-hard" ? "bg-red-500" : "bg-amber-500")} aria-hidden />
                  <span className="grid min-w-0 gap-0.5">
                    <span className="line-clamp-2 text-sm">{text.slice(s.start, s.end)}</span>
                    <span className="text-xs text-muted-foreground">
                      {gradeText.replace("{grade}", String(Math.round(s.grade)))} · {[s.long && longText.replace("{words}", String(s.words)), s.dense && denseText].filter(Boolean).join(" ") || longText.replace("{words}", String(s.words))}
                    </span>
                  </span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}

      {swapList.length > 0 && (
        <div className="grid gap-1.5 pt-1">
          <p className="text-xs font-medium text-muted-foreground">{swapsTitle}</p>
          <div ref={chips} className="flex flex-wrap gap-1.5">
            {swapList.map((s, index) => (
              <button key={s.word.toLowerCase()} type="button" onClick={() => swap(s.word, s.plain, index)} aria-label={swapLabel.replace("{word}", s.word.toLowerCase()).replace("{plain}", s.plain)} className={chipClass}>
                <span className="text-muted-foreground">{s.word.toLowerCase()}</span>
                <ArrowRight aria-hidden className="size-3 text-muted-foreground" />
                <span className="font-medium">{s.plain}</span>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}
